import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第三册：培养技能 · 全册易错点 · 第1–21课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第三册：培养技能 · 全册易错点 · 第1–21课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-3/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册易错点","link":"/life/english/new-concept/book-3/mistakes"},"next":{"text":"第三册：培养技能 · 全册易错点 · 第22–44课","link":"/life/english/new-concept/book-3/mistakes-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册易错点","link":"/life/english/new-concept/book-3/mistakes"},"next":{"text":"第三册：培养技能 · 全册易错点 · 第22–44课","link":"/life/english/new-concept/book-3/mistakes-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-3/mistakes-part-01.md","filePath":"life/english/new-concept/book-3/mistakes-part-01.md"}'),l={name:"life/english/new-concept/book-3/mistakes-part-01.md"};function r(i,e,s,h,p,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-全册易错点-·-第1–21课" tabindex="-1">第三册：培养技能 · 全册易错点 · 第1–21课 <a class="header-anchor" href="#第三册-培养技能-·-全册易错点-·-第1–21课" aria-label="Permalink to &quot;第三册：培养技能 · 全册易错点 · 第1–21课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="第三册-培养技能-·-全册易错点" tabindex="-1">第三册：培养技能 · 全册易错点 <a class="header-anchor" href="#第三册-培养技能-·-全册易错点" aria-label="Permalink to &quot;第三册：培养技能 · 全册易错点 {#第三册-培养技能-·-全册易错点}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="l1-·-定语从句与证据限定" tabindex="-1">L1 · 定语从句与证据限定 <a class="header-anchor" href="#l1-·-定语从句与证据限定" aria-label="Permalink to &quot;L1 · 定语从句与证据限定 {#l1-·-定语从句与证据限定}&quot;">​</a></h2><p>The tracks that appeared overnight 中 that 作主语，不能删；The tracks that we photographed 中 that 作宾语，可以删。</p><p><strong>对照例句：</strong> The tracks that we found near the gate may belong to a large dog.</p><p>that we found near the gate 修饰 tracks，that 作 found 的宾语；may 表示不确定推测。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-001">回看讲解和练习</a></p><h2 id="l2-·-过去进行时与突发事件" tabindex="-1">L2 · 过去进行时与突发事件 <a class="header-anchor" href="#l2-·-过去进行时与突发事件" aria-label="Permalink to &quot;L2 · 过去进行时与突发事件 {#l2-·-过去进行时与突发事件}&quot;">​</a></h2><p>I was knowing the answer 不适合表达当时知道答案，应写 I knew the answer；进行时强调过程而非单纯过去时间。</p><p><strong>对照例句：</strong> I was checking the clock when a loose screw fell onto the floor.</p><p>was checking 提供背景，fell 引入一个短暂的新事件；when 连接两者。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-002">回看讲解和练习</a></p><h2 id="l3-·-过去完成时的时间参照" tabindex="-1">L3 · 过去完成时的时间参照 <a class="header-anchor" href="#l3-·-过去完成时的时间参照" aria-label="Permalink to &quot;L3 · 过去完成时的时间参照 {#l3-·-过去完成时的时间参照}&quot;">​</a></h2><p>Ancient builders had built it in 900 若没有另一个过去参照点，通常写 built 更直接；古老不等于过去完成。</p><p><strong>对照例句：</strong> By the time the team reached the chamber, water had damaged several paintings.</p><p>reached 是过去参照点；had damaged 把损坏放在到达之前；by the time 表示到那个时间为止。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-003">回看讲解和练习</a></p><h2 id="l4-·-used-to-与过去习惯" tabindex="-1">L4 · used to 与过去习惯 <a class="header-anchor" href="#l4-·-used-to-与过去习惯" aria-label="Permalink to &quot;L4 · used to 与过去习惯 {#l4-·-used-to-与过去习惯}&quot;">​</a></h2><p>I am used to work early 应改为 I am used to working early；若说过去早上班，则是 I used to work early。</p><p><strong>对照例句：</strong> Leo used to hide his work clothes, but now he talks openly about his job.</p><p>used to hide 表示已改变的习惯；but now 与前半句构成明确时间对比。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-004">回看讲解和练习</a></p><h2 id="l5-·-间接疑问句的陈述语序" tabindex="-1">L5 · 间接疑问句的陈述语序 <a class="header-anchor" href="#l5-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;L5 · 间接疑问句的陈述语序 {#l5-·-间接疑问句的陈述语序}&quot;">​</a></h2><p>The editor asked how many households had the survey covered 错在保留问句倒装，间接疑问从句要恢复陈述语序。</p><p><strong>对照例句：</strong> The editor asked how many households the survey had covered.</p><p>how many households 为 covered 的宾语，the survey 为主语；had covered 表示调查在询问之前已进行。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-005">回看讲解和练习</a></p><h2 id="l6-·-一般过去时的被动语态" tabindex="-1">L6 · 一般过去时的被动语态 <a class="header-anchor" href="#l6-·-一般过去时的被动语态" aria-label="Permalink to &quot;L6 · 一般过去时的被动语态 {#l6-·-一般过去时的被动语态}&quot;">​</a></h2><p>The accident was happened 不成立，因为 happen 不带直接宾语；应写 The accident happened。</p><p><strong>对照例句：</strong> Two display cases were damaged before the alarm was raised.</p><p>were damaged 与 was raised 均为过去时被动；cases 为复数，alarm 为单数。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-006">回看讲解和练习</a></p><h2 id="l7-·-可数与不可数名词" tabindex="-1">L7 · 可数与不可数名词 <a class="header-anchor" href="#l7-·-可数与不可数名词" aria-label="Permalink to &quot;L7 · 可数与不可数名词 {#l7-·-可数与不可数名词}&quot;">​</a></h2><p>many money 应为 much money 或 a lot of money；many banknotes 则正确，因为 banknote 可数。</p><p><strong>对照例句：</strong> Several fragments were missing, but most of the printed number was still visible.</p><p>several fragments 为复数；most of the printed number 指单个号码的部分，谓语用 was。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-007">回看讲解和练习</a></p><h2 id="l8-·-地点介词与移动路径" tabindex="-1">L8 · 地点介词与移动路径 <a class="header-anchor" href="#l8-·-地点介词与移动路径" aria-label="Permalink to &quot;L8 · 地点介词与移动路径 {#l8-·-地点介词与移动路径}&quot;">​</a></h2><p>across the forest 强调横穿整个林区，through the forest 强调在林中穿行；路线视角不同，不宜机械判为同义。</p><p><strong>对照例句：</strong> A narrow path runs through the forest and ends at the old gate.</p><p>through 描述穿过内部空间，at 把大门作为终点；runs 与 ends 共用单数主语 path。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-008">回看讲解和练习</a></p><h2 id="l9-·-比较级与比较对象一致" tabindex="-1">L9 · 比较级与比较对象一致 <a class="header-anchor" href="#l9-·-比较级与比较对象一致" aria-label="Permalink to &quot;L9 · 比较级与比较对象一致 {#l9-·-比较级与比较对象一致}&quot;">​</a></h2><p>very faster 应改为 much faster 或 a little faster；very fast 则是原级搭配。</p><p><strong>对照例句：</strong> The second ramp was slightly steeper than the first, so the cart moved faster.</p><p>slightly 修饰 steeper，than the first 省略 ramp；faster 在此修饰 moved。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-009">回看讲解和练习</a></p><h2 id="l10-·-过去反事实条件句" tabindex="-1">L10 · 过去反事实条件句 <a class="header-anchor" href="#l10-·-过去反事实条件句" aria-label="Permalink to &quot;L10 · 过去反事实条件句 {#l10-·-过去反事实条件句}&quot;">​</a></h2><p>If they would have heard the alarm 不符合此处标准反事实条件结构，应写 If they had heard the alarm。</p><p><strong>对照例句：</strong> If the crew had received the warning earlier, they might have changed course.</p><p>had received 假设过去条件，might have changed 表示可能而非必然的不同结果。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-010">回看讲解和练习</a></p><h2 id="l11-·-转述要求与否定命令" tabindex="-1">L11 · 转述要求与否定命令 <a class="header-anchor" href="#l11-·-转述要求与否定命令" aria-label="Permalink to &quot;L11 · 转述要求与否定命令 {#l11-·-转述要求与否定命令}&quot;">​</a></h2><p>He told me don&#39;t touch it 应改为 He told me not to touch it；保留直接引语时则需引号和相应标点。</p><p><strong>对照例句：</strong> The officer asked me to place the sealed box on the counter.</p><p>asked 为谓语，me 为宾语，to place 为宾语补足语；执行 place 的人是 me。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-011">回看讲解和练习</a></p><h2 id="l12-·-第二条件句的假设距离" tabindex="-1">L12 · 第二条件句的假设距离 <a class="header-anchor" href="#l12-·-第二条件句的假设距离" aria-label="Permalink to &quot;L12 · 第二条件句的假设距离 {#l12-·-第二条件句的假设距离}&quot;">​</a></h2><p>If I would live there 混淆条件与结果；通常写 If I lived there, I would ...。</p><p><strong>对照例句：</strong> If I lived on a remote island, I would choose a reliable radio over a television.</p><p>lived 表假设而非实际过去；would choose 是设想的选择；over 表示优先于。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-012">回看讲解和练习</a></p><h2 id="l13-·-强调句的焦点" tabindex="-1">L13 · 强调句的焦点 <a class="header-anchor" href="#l13-·-强调句的焦点" aria-label="Permalink to &quot;L13 · 强调句的焦点 {#l13-·-强调句的焦点}&quot;">​</a></h2><p>It was yesterday when he called 不宜作为本课标准强调句答案；强调时间用 It was yesterday that he called。</p><p><strong>对照例句：</strong> It was the gardener&#39;s voice that finally reassured the visitor.</p><p>It was ... that 强调主语 the gardener&#39;s voice；还原为 The gardener&#39;s voice finally reassured the visitor。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-013">回看讲解和练习</a></p><h2 id="l14-·-although-与-despite" tabindex="-1">L14 · although 与 despite <a class="header-anchor" href="#l14-·-although-与-despite" aria-label="Permalink to &quot;L14 · although 与 despite {#l14-·-although-与-despite}&quot;">​</a></h2><p>Despite he helped us 结构不完整，应为 Despite helping us 或 Although he helped us。</p><p><strong>对照例句：</strong> Although the businessman funded a clinic, his illegal methods still harmed the community.</p><p>although 从句承认善举，主句保留对手段的评价；still 强化让步关系。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-014">回看讲解和练习</a></p><h2 id="l15-·-数量修饰语与-worth" tabindex="-1">L15 · 数量修饰语与 worth <a class="header-anchor" href="#l15-·-数量修饰语与-worth" aria-label="Permalink to &quot;L15 · 数量修饰语与 worth {#l15-·-数量修饰语与-worth}&quot;">​</a></h2><p>a two-minutes repair 错把复合修饰语中的单位写成复数；two minutes of repair work 则可用复数。</p><p><strong>对照例句：</strong> A two-minute repair saved a toy worth only three pounds.</p><p>two-minute 修饰 repair，minute 不用复数；worth only three pounds 后置修饰 toy。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-015">回看讲解和练习</a></p><h2 id="l16-·-one、it-与名词替代" tabindex="-1">L16 · one、it 与名词替代 <a class="header-anchor" href="#l16-·-one、it-与名词替代" aria-label="Permalink to &quot;L16 · one、it 与名词替代 {#l16-·-one、it-与名词替代}&quot;">​</a></h2><p>I lost my pen and bought it 表示买回同一支笔；若买了一支替代品，应写 bought a new one。</p><p><strong>对照例句：</strong> Of the two lambs, the one with a dark ear belonged to our neighbour.</p><p>the one 替代 lamb，with a dark ear 限定具体是哪一只；belonged 的主语仍为单数。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-016">回看讲解和练习</a></p><h2 id="l17-·-最高级的范围与倍数" tabindex="-1">L17 · 最高级的范围与倍数 <a class="header-anchor" href="#l17-·-最高级的范围与倍数" aria-label="Permalink to &quot;L17 · 最高级的范围与倍数 {#l17-·-最高级的范围与倍数}&quot;">​</a></h2><p>one of the longest bridge 应为 one of the longest bridges；比较集合必须由复数名词表示。</p><p><strong>对照例句：</strong> The new footbridge is twice as long as the wooden one it replaced.</p><p>twice as long as 表示明确倍数；one 替代 footbridge；it replaced 为省略宾语关系词的定语从句。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-017">回看讲解和练习</a></p><h2 id="l18-·-感官动词后的补语" tabindex="-1">L18 · 感官动词后的补语 <a class="header-anchor" href="#l18-·-感官动词后的补语" aria-label="Permalink to &quot;L18 · 感官动词后的补语 {#l18-·-感官动词后的补语}&quot;">​</a></h2><p>We saw the panel to move 在主动感官结构中多了 to；应写 move 或 moving，取决于观察视角。</p><p><strong>对照例句：</strong> We watched the metal rings rotating while a low tone filled the room.</p><p>watched 加宾语 the metal rings 和 rotating，呈现观看中的持续动作；while 连接同时背景。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-018">回看讲解和练习</a></p><h2 id="l19-·-have-加宾语加过去分词" tabindex="-1">L19 · have 加宾语加过去分词 <a class="header-anchor" href="#l19-·-have-加宾语加过去分词" aria-label="Permalink to &quot;L19 · have 加宾语加过去分词 {#l19-·-have-加宾语加过去分词}&quot;">​</a></h2><p>He had his wallet stolen 通常表示钱包被偷的遭遇，不能仅凭 had 就翻译为“他请人偷钱包”。</p><p><strong>对照例句：</strong> After the gate broke, we had a new lock fitted to keep the dog safely inside.</p><p>had 为一般过去时，a new lock 是宾语，fitted 是过去分词补语；to keep 表目的。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-019">回看讲解和练习</a></p><h2 id="l20-·-过去将来时与计划结果" tabindex="-1">L20 · 过去将来时与计划结果 <a class="header-anchor" href="#l20-·-过去将来时与计划结果" aria-label="Permalink to &quot;L20 · 过去将来时与计划结果 {#l20-·-过去将来时与计划结果}&quot;">​</a></h2><p>He was going to fly at dawn 不保证他确实起飞；如果天气取消计划，原句仍然可以成立。</p><p><strong>对照例句：</strong> The pilot believed that the lighter engine would extend the aircraft&#39;s range.</p><p>believed 建立过去视点；would extend 指相对于相信时刻尚未发生的预期。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-020">回看讲解和练习</a></p><h2 id="l21-·-完成时不定式的先后关系" tabindex="-1">L21 · 完成时不定式的先后关系 <a class="header-anchor" href="#l21-·-完成时不定式的先后关系" aria-label="Permalink to &quot;L21 · 完成时不定式的先后关系 {#l21-·-完成时不定式的先后关系}&quot;">​</a></h2><p>He seems to won 不成立；强调此前获胜应写 seems to have won，描述经常获胜则可用 seems to win。</p><p><strong>对照例句：</strong> The retired athlete appears to have inspired a new generation of coaches.</p><p>appears 为现在判断，to have inspired 指此前发生并留下影响的行为。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-021">回看讲解和练习</a></p>',110)])])}const f=a(l,[["render",r]]);export{g as __pageData,f as default};
